VALUES ('703816f3-fc86-5270-9363-471f959f2711', NULL, 'Урок 1: Hello and Goodbye', 'Практика слов, слушания и короткой речи на английском.', 0, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"Hello.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["Hello.","Hi, I am new.","Goodbye. See you."],"points":10,"prompt":"Which phrase best helps you: greet a teacher and say goodbye politely.","type":"multiple_choice"},{"answer":["Hello.","Hi, I am new.","Goodbye. See you."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["Hello.","Hi, I am new.","Goodbye. See you."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Say hello, introduce yourself, and say goodbye.","type":"recording"}],"final_task":{"learner_instruction":"Say hello, introduce yourself, and say goodbye. Speak for at least 20 seconds.","minimum_seconds":20,"required_language":["Hello.","Hi, I am new."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable