ss.","focus":"Clear names, greetings, and final consonants.","model":"Hello.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t01_l01_vocab_01","example":"I use the word ''hello'' in this lesson.","image_key":"a1_study_t01_l01_vocab_01","meaning":"A key word used in this lesson: hello.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''hello''.","word":"hello"},{"audio_key":"a1_study_t01_l01_vocab_02","example":"I use the word ''hi'' in this lesson.","image_key":"a1_study_t01_l01_vocab_02","meaning":"A key word used in this lesson: hi.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''hi''.","word":"hi"},{"audio_key":"a1_study_t01_l01_vocab_03","example":"I use the word ''goodbye'' in this lesson.","image_key":"a1_study_t01_l01_vocab_03","meaning":"A key word used in this lesson: goodbye.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''goodbye''.","word":"goodbye"},{"audio_key":"a1_study_t01_l01_vocab_04","example":"I use the word ''teacher'' in this lesson.","image_key":"a1_study_t01_l01_vocab_04","meaning":"A key word used in this lesson: teacher.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''teacher''.","word":"teacher"},{"audio_key":"a1_study_t01_l01_vocab_05","example":"I use the word ''student'' in this lesson.","image_key":"a1_study_t01_l01_vocab_05","meaning":"A key word used in this lesson: student.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''student''.","word":"student"}]},"title":"Hello and Goodbye"}'::jsonb, NOW(), NOW())
