INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('d54f3b32-da3d-5c50-b683-459ca599f911', NULL, 'Урок 8: Please Repeat', 'Практика слов, слушания и короткой речи на английском.', 7, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"Please repeat.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["Please repeat.","Again, please.","Please speak slowly."],"points":10,"prompt":"Which phrase best helps you: ask for repetition and slower speech.","type":"multiple_choice"},{"answer":["Please repeat.","Again, please.","Please speak slowly."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["Please repeat.","Again, please.","Please speak slowly."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Repair a conversation when you do not understand.","type":"recording"}],"final_task":{"learner_instruction":"Repair a conversation when you do not understand. Speak for at least 55 seconds.","minimum_seconds":55,"required_language":["Please repeat.","Again, please."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Repair a conversation when you do not understand.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T01_L08","lesson_number":8,"mission":"Ask for repetition and slower speech.","objectives":["Use key words and phrases to ask for repetition and slower speech.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on please repeat.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to ask for repetition and slower speech.","examples":["Please repeat.","Again, please.","Please speak slowly."],"pattern":"polite requests","point":"polite requests"}],"phrases":[{"audio_key":"a1_study_t01_l08_phrase_01","example":"Please repeat.","formality":"neutral","phrase":"Please repeat.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t01_l08_phrase_02","example":"Again, please.","formality":"neutral","phrase":"Again, please.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t01_l08_phrase_03","example":"Please speak slowly.","formality":"neutral","phrase":"Please speak slowly.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t01_l08_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Clear names, greetings, and final consonants.","model":"Please repeat.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t01_l08_vocab_01","example":"I use the word ''repeat'' in this lesson.","image_key":"a1_study_t01_l08_vocab_01","meaning":"A key word used in this lesson: repeat.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''repeat''.","word":"repeat"},{"audio_key":"a1_study_t01_l08_vocab_02","example":"I use the word ''again'' in this lesson.","image_key":"a1_study_t01_l08_vocab_02","meaning":"A key word used in this lesson: again.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''again''.","word":"again"},{"audio_key":"a1_study_t01_l08_vocab_03","example":"I use the word ''slowly'' in this lesson.","image_key":"a1_study_t01_l08_vocab_03","meaning":"A key word used in this lesson: slowly.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''slowly''.","word":"slowly"},{"audio_key":"a1_study_t01_l08_vocab_04","example":"I use the word ''understand'' in this lesson.","image_key":"a1_study_t01_l08_vocab_04","meaning":"A key word used in this lesson: understand.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''understand''.","word":"understand"},{"audio_key":"a1_study_t01_l08_vocab_05","example":"I use the word ''sorry'' in this lesson.","image_key":"a1_study_t01_l08_vocab_05","meaning":"A key word used in this lesson: sorry.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''sorry''.","word":"sorry"}]},"title":"Please Repeat"}'::jsonb, NOW(), NOW())
