INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('b31e7f41-7e31-5fcd-b93c-8eba1e0d1860', NULL, 'Урок 9: Meet a Classmate', 'Практика слов, слушания и короткой речи на английском.', 8, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"Are you new?","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["Are you new?","Yes, I am.","Let''s practice together."],"points":10,"prompt":"Which phrase best helps you: use greetings, names, countries, and languages together.","type":"multiple_choice"},{"answer":["Are you new?","Yes, I am.","Let''s practice together."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["Are you new?","Yes, I am.","Let''s practice together."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Have a six-turn conversation with a classmate.","type":"recording"}],"final_task":{"learner_instruction":"Have a six-turn conversation with a classmate. Speak for at least 60 seconds.","minimum_seconds":60,"required_language":["Are you new?","Yes, I am."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Have a six-turn conversation with a classmate.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T01_L09","lesson_number":9,"mission":"Use greetings, names, countries, and languages together.","objectives":["Use key words and phrases to use greetings, names, countries, and languages together.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on meet a classmate.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to use greetings, names, countries, and languages together.","examples":["Are you new?","Yes, I am.","Let''s practice together."],"pattern":"yes/no questions with be","point":"yes/no questions with be"}],"phrases":[{"audio_key":"a1_study_t01_l09_phrase_01","example":"Are you new?","formality":"neutral","phrase":"Are you new?","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t01_l09_phrase_02","example":"Yes, I am.","formality":"neutral","phrase":"Yes, I am.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t01_l09_phrase_03","example":"Let''s practice together.","formality":"neutral","phrase":"Let''s practice together.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t01_l09_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Clear names, greetings, and final consonants.","model":"Are you new?","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t01_l09_vocab_01","example":"I use the word ''partner'' in this lesson.","image_key":"a1_study_t01_l09_vocab_01","meaning":"A key word used in this lesson: partner.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''partner''.","word":"partner"},{"audio_key":"a1_study_t01_l09_vocab_02","example":"I use the word ''question'' in this lesson.","image_key":"a1_study_t01_l09_vocab_02","meaning":"A key word used in this lesson: question.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''question''.","word":"question"},{"audio_key":"a1_study_t01_l09_vocab_03","example":"I use the word ''answer'' in this lesson.","image_key":"a1_study_t01_l09_vocab_03","meaning":"A key word used in this lesson: answer.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''answer''.","word":"answer"},{"audio_key":"a1_study_t01_l09_vocab_04","example":"I use the word ''friend'' in this lesson.","image_key":"a1_study_t01_l09_vocab_04","meaning":"A key word used in this lesson: friend.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''friend''.","word":"friend"},{"audio_key":"a1_study_t01_l09_vocab_05","example":"I use the word ''new'' in this lesson.","image_key":"a1_study_t01_l09_vocab_05","meaning":"A key word used in this lesson: new.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''new''.","word":"new"}]},"title":"Meet a Classmate"}'::jsonb, NOW(), NOW())
